<script setup>
import {ref,computed,watch,nextTick,onBeforeUnmount} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {api,errorMessage} from '../workspace-api'
import {auth} from '../auth'
import PartnerIdentity from './PartnerIdentity.vue'
import ReplyMarkdown from './ReplyMarkdown.vue'
import StudioIcon from './StudioIcon.vue'
import PartnerModelPicker from './PartnerModelPicker.vue'
import SkillBrief from './SkillBrief.vue'
const props=defineProps({partner:Object,partners:Array,skills:Array,enabled:Boolean,projects:Array})
const route=useRoute(),router=useRouter(),selected=ref(''),conversation=ref(null),sessions=ref([]),resources=ref([]),draft=ref(''),pending=ref(null),attachments=ref([]),skill=ref('auto'),tab=ref('tasks'),search=ref(''),menu=ref(''),error=ref(''),busy=ref(false),loading=ref(false),uploading=ref(false),older=ref(false),nextBefore=ref(null),scroll=ref(null),fileInput=ref(null),bottom=ref(true),resourcePanel=ref(false),preview=ref(null),now=ref(Date.now())
const modelProfileId=ref(''),modelReady=ref(false),brief=ref(false)
const recommendedSkills=computed(()=>(props.partner.skillIds||[props.partner.skillId]).map(id=>props.skills.find(s=>s.id===id)).filter(Boolean))
const reusableResources=computed(()=>resources.value.filter(r=>!r.conversationId||r.conversationId===selected.value).filter(r=>!attachments.value.some(a=>a.id===r.id)))
function startSkill(s){skill.value=s.id;if(!draft.value.trim())draft.value=s.example;menu.value=''}
function presetSkill(){if(active.value)return;const id=route.query.skill;if(!id)return;const s=props.skills.find(s=>s.id===id&&s.kind==='TEXT');if(!s||s.partnerId!==props.partner.id){error.value='此技能不属于当前伙伴，请从技能广场重新进入。';return}startSkill(s)}
function presetResource(){const id=route.query.resource;if(typeof id!=='string')return;const r=reusableResources.value.find(r=>r.id===id);if(r){attachResource(r);if(!draft.value.trim())draft.value='请基于附件中的 MCP 工具结果完成任务，区分工具数据和分析建议。'}else error.value='指定资源不存在或不属于当前任务。'}
function attachResource(r){if(attachments.value.length>=3){error.value='每条消息最多3个附件';return}attachments.value.push(r);menu.value=''}
async function removeTask(){if(!conversation.value||running.value||pending.value||!window.confirm('删除此任务及其上传材料和生成文件？此操作无法撤销。'))return;const t=epoch;try{await api.delete(base.value+'/conversations/'+selected.value,{params:{revision:conversation.value.revision},signal:controller.signal});if(t===epoch)await open()}catch(e){if(t===epoch)error.value=errorMessage(e)}}
let epoch=0,controller,refreshing=false
const base=computed(()=>'/ai/work/partners/'+props.partner.id),active=computed(()=>!!selected.value),running=computed(()=>conversation.value?.turns.at(-1)?.status==='RUNNING'),shownSessions=computed(()=>sessions.value.filter(x=>x.title.includes(search.value))),shownResources=computed(()=>resources.value.filter(x=>x.name.includes(search.value))),taskResources=computed(()=>resources.value.filter(x=>x.conversationId===selected.value)),currentSkill=computed(()=>props.skills.find(s=>s.id===skill.value)),textSkills=computed(()=>props.skills.filter(s=>s.kind==='TEXT')),storageKey=id=>'partner-chat:'+auth.user?.id+':'+props.partner.id+':'+id
function uuid(){const b=crypto.getRandomValues(new Uint8Array(16));b[6]=(b[6]&15)|64;b[8]=(b[8]&63)|128;return [...b].map((v,i)=>([4,6,8,10].includes(i)?'-':'')+v.toString(16).padStart(2,'0')).join('')}
function contentUrl(r,inline=false){return '/api'+base.value+'/resources/'+r.id+'/content'+(inline?'?preview=true':'')}
function date(value){return new Date(value).toLocaleString('zh-CN',{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'})}
function elapsed(turn){return Math.max(0,Math.floor((now.value-new Date(turn.createdAt).getTime())/1000))+'秒'}
async function latest(){await nextTick();if(scroll.value){scroll.value.scrollTop=scroll.value.scrollHeight;bottom.value=true}}
function accept(data,replace=false){const follow=bottom.value;if(replace||!conversation.value){conversation.value=data;nextBefore.value=data.nextBefore??null}else{const turns=new Map(conversation.value.turns.map(t=>[t.id,t]));for(const t of data.turns)turns.set(t.id,t);conversation.value={...data,turns:[...turns.values()]}}if(pending.value&&data.turns.some(t=>t.id===pending.value.requestId)){sessionStorage.removeItem(storageKey(data.id));pending.value=null}if(follow)latest()}
async function lists(t){const [a,b]=await Promise.all([api.get(base.value+'/conversations',{signal:controller.signal}),api.get(base.value+'/resources',{signal:controller.signal})]);if(t===epoch){sessions.value=a.data;resources.value=b.data}}
async function refresh(){if(refreshing||loading.value)return;refreshing=true;const t=epoch;try{if(selected.value){const r=await api.get(base.value+'/conversations/'+selected.value+'/page',{signal:controller.signal});if(t===epoch){const wasRunning=running.value;accept(r.data);if(wasRunning&&!running.value)await lists(t)}}else await lists(t)}catch(e){if(t===epoch&&e.code!=='ERR_CANCELED'&&!(pending.value&&e.response?.status===400))error.value=errorMessage(e)}finally{refreshing=false}}
async function open(id='',syncUrl=true){const t=++epoch;controller?.abort();controller=new AbortController();selected.value=id;conversation.value=null;pending.value=null;draft.value='';skill.value='auto';brief.value=false;attachments.value=[];error.value='';menu.value='';resourcePanel.value=false;busy.value=false;loading.value=true;nextBefore.value=null;bottom.value=true
 try{if(id){const saved=sessionStorage.getItem(storageKey(id));if(saved)pending.value=JSON.parse(saved)}if(syncUrl)await router.push({query:{conversation:id||undefined}});await lists(t);if(id){const r=await api.get(base.value+'/conversations/'+id+'/page',{signal:controller.signal});if(t===epoch)accept(r.data,true)}}catch(e){if(t===epoch&&e.code!=='ERR_CANCELED')error.value=pending.value?'上一条消息状态待确认，请刷新记录或重试同一条消息。':errorMessage(e)}finally{if(t===epoch){loading.value=false;if(!id)presetSkill();presetResource();await latest()}}}
async function loadOlder(){if(older.value||nextBefore.value===null||loading.value)return;older.value=true;const t=epoch,el=scroll.value,h=el.scrollHeight,top=el.scrollTop;try{const r=await api.get(base.value+'/conversations/'+selected.value+'/page',{params:{before:nextBefore.value},signal:controller.signal});if(t!==epoch)return;conversation.value.turns=[...r.data.turns,...conversation.value.turns];nextBefore.value=r.data.nextBefore;await nextTick();el.scrollTop=top+el.scrollHeight-h}catch(e){if(t===epoch&&e.code!=='ERR_CANCELED')error.value=errorMessage(e)}finally{older.value=false}}
function onScroll(){const el=scroll.value;if(!el)return;bottom.value=el.scrollHeight-el.scrollTop-el.clientHeight<100;if(el.scrollTop<70)loadOlder()}
async function upload(event){const files=[...event.target.files];event.target.value='';if(files.length+attachments.value.length>3){error.value='每条消息最多3个附件';return}const t=epoch;uploading.value=true;error.value='';menu.value='';try{for(const file of files){if(file.size>1024*1024)throw new Error('每个文件须小于1MB');const form=new FormData();form.append('file',file);const r=await api.post(base.value+'/files',form,{signal:controller.signal});if(t!==epoch)return;attachments.value.push(r.data)}}catch(e){if(t===epoch&&e.code!=='ERR_CANCELED')error.value=e.response?errorMessage(e):e.message}finally{if(t===epoch)uploading.value=false}}
async function send(retry=false){if(busy.value||running.value||loading.value||uploading.value||!props.enabled||!modelReady.value)return;if(!retry&&(!draft.value.trim()||pending.value))return;busy.value=true;error.value='';menu.value='';const t=epoch;let input=retry?pending.value:null
 try{if(!input){if(!selected.value){selected.value=uuid();await router.push({query:{conversation:selected.value}})}input={conversationId:selected.value,requestId:uuid(),expectedRevision:conversation.value?.revision||0,text:draft.value.trim(),skillId:skill.value,modelProfileId:modelProfileId.value,attachmentIds:attachments.value.map(x=>x.id)}}if(t!==epoch)return;sessionStorage.setItem(storageKey(input.conversationId),JSON.stringify(input));pending.value=input;draft.value='';attachments.value=[];bottom.value=true;await latest();const r=await api.post(base.value+'/jobs',input,{signal:controller.signal});if(t!==epoch)return;accept(r.data);await lists(t)}catch(e){if(t!==epoch||e.code==='ERR_CANCELED')return;if([400,409].includes(e.response?.status)){sessionStorage.removeItem(storageKey(input.conversationId));pending.value=null;draft.value=input.text;attachments.value=resources.value.filter(r=>input.attachmentIds?.includes(r.id));error.value=errorMessage(e)}else error.value='发送状态待确认，请刷新记录。重试同一条消息会复用原记录。'}finally{if(t===epoch)busy.value=false}}
async function stop(){const t=epoch;try{const r=await api.post(base.value+'/conversations/'+selected.value+'/stop',{}, {signal:controller.signal});if(t===epoch)accept(r.data)}catch(e){if(t===epoch)error.value=errorMessage(e)}}
function exportLegacy(turn){const url=URL.createObjectURL(new Blob([turn.answer],{type:'text/markdown;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='回复文稿.md';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
watch(()=>route.query.skill,()=>{if(!busy.value&&!pending.value)presetSkill()})
watch(()=>route.query.conversation,id=>{if((id||'')!==selected.value)open(typeof id==='string'?id:'',false)})
watch([()=>props.partner.id,()=>auth.user?.id],()=>open(typeof route.query.conversation==='string'?route.query.conversation:'',false),{immediate:true})
const timer=setInterval(()=>{now.value=Date.now();if(running.value||pending.value)refresh()},1500)
onBeforeUnmount(()=>{epoch++;controller?.abort();clearInterval(timer)})
</script>
<template>
<section class="partner-surface" :class="{'in-task':active}">
 <header class="surface-header"><div class="surface-crumb"><RouterLink to="/skills?tab=partners">工作伙伴</RouterLink><span>›</span><button @click="open()">{{partner.name}}</button><template v-if="active"><span>›</span><details class="task-switch"><summary>{{conversation?.title||'新任务'}} ⌄</summary><div><button v-for="s in sessions" :key="s.id" @click="open(s.id)">{{s.title}}</button></div></details></template></div><div class="surface-actions"><button v-if="active" :disabled="running||!!pending||busy" @click="removeTask" aria-label="删除当前任务">删除任务</button><button v-if="active" @click="open()" title="新任务" aria-label="新任务"><StudioIcon name="plus"/></button><button v-if="active" :class="{selected:resourcePanel}" @click="resourcePanel=!resourcePanel" aria-label="任务资源" title="任务资源"><StudioIcon name="folder"/><span>{{taskResources.length}}</span></button><RouterLink :to="'/partners/'+partner.id+'/details?profile=1'" title="我的偏好"><StudioIcon name="person" :size="20"/></RouterLink></div></header>
 <div v-if="!active" class="partner-landing-scroll"><div class="partner-landing">
  <PartnerIdentity :partner="partner" :partners="partners"/>
  <p v-if="!enabled" class="surface-notice">此伙伴已被限制，可在伙伴详情 → 管理中调整授权。历史任务和资源仍可查看。</p>
  <div class="partner-quick-actions" aria-label="伙伴任务工具箱"><button v-for="s in recommendedSkills" :key="s.id" @click="startSkill(s)" :disabled="!enabled||!!pending"><StudioIcon :name="s.icon" :size="19"/><span><strong>{{s.name}}</strong><small>{{s.output}}</small></span></button></div><p class="partner-delivery-note">可上传 Word、文字 PDF 与数据表；回复可下载为 Word，表格可导出 Excel。</p><div id="landing-composer"></div>
  <div v-if="partner.workspace==='narrative-ppt'" class="ppt-link"><RouterLink to="/presentation">打开 NarrativePPT 制作工作台 <StudioIcon name="arrow" :size="16"/></RouterLink></div>
  <div v-if="partner.id==='travel'" class="ppt-link"><RouterLink to="/tasks">打开有天气与地点依据的出行规划 →</RouterLink></div><div class="landing-records"><div class="records-toolbar"><nav><button v-for="[key,label] in [['tasks','任务'],['automation','自动化'],['resources','资源']]" :key="key" :class="{active:tab===key}" @click="tab=key">{{label}}</button></nav><div class="record-search"><StudioIcon name="search" :size="17"/><input v-model="search" placeholder="搜索" aria-label="搜索任务或资源"></div></div>
   <template v-if="tab==='tasks'"><button v-for="s in shownSessions" :key="s.id" class="task-list-row" @click="open(s.id)"><span><strong>{{s.title}}</strong><small v-if="s.status==='RUNNING'">正在执行</small></span><time>{{date(s.updatedAt)}}</time><StudioIcon name="arrow" :size="16"/></button><div v-if="!shownSessions.length" class="landing-empty"><StudioIcon name="chat" :size="36"/><p>{{search?'没有匹配的任务':'从上方发起你的第一个任务'}}</p></div><RouterLink class="legacy-link" :to="'/work/'+partner.skillId">查看旧版单次任务文稿 ›</RouterLink><RouterLink v-for="project in projects" :key="project.id" class="task-list-row" to="/presentation"><strong>{{project.title||project.name||'演示项目'}}</strong><small>打开PPT工作台 ›</small></RouterLink></template>
   <template v-else-if="tab==='resources'"><div v-for="r in shownResources" :key="r.id" class="resource-list-row"><a :href="contentUrl(r)" :download="r.name"><StudioIcon :name="r.mime.startsWith('image/')?'layout':'document'" :size="24"/><strong>{{r.name}}</strong><small>{{r.kind==='upload'?'上传材料':'生成文件'}}</small></a><button v-if="r.mime.startsWith('image/')" @click="preview=r">预览</button><button v-if="r.conversationId" @click="open(r.conversationId)">来源任务</button><time>{{date(r.createdAt)}}</time></div><div v-if="!shownResources.length" class="landing-empty"><StudioIcon name="folder" :size="36"/><p>任务中的文稿、表格和图片会保存在这里</p></div></template>
   <div v-else class="landing-empty"><StudioIcon name="clock" :size="36"/><p>暂未接入定时自动化</p></div>
  </div>
 </div></div>
 <template v-else>
  <aside v-if="resourcePanel" class="task-resource-panel"><div><h2>本任务资源</h2><button @click="resourcePanel=false" aria-label="关闭资源"><StudioIcon name="close"/></button></div><a v-for="r in taskResources" :key="r.id" :href="contentUrl(r)" :download="r.name"><StudioIcon name="document" :size="20"/><span>{{r.name}}<small>{{r.kind==='upload'?'上传材料':'生成文件'}}</small></span><StudioIcon name="download" :size="16"/></a><p v-if="!taskResources.length">此任务暂时没有文件资源</p></aside>
  <div ref="scroll" class="task-message-scroll" @scroll.passive="onScroll"><div class="task-message-width">
   <button v-if="nextBefore!==null" class="load-older" @click="loadOlder" :disabled="older">{{older?'正在加载…':'加载更早的对话'}}</button><p v-if="loading" class="loading-state">正在读取任务…</p>
   <article v-for="turn in conversation?.turns||[]" :key="turn.id" class="task-turn" :data-turn="turn.id"><div class="user-message"><p>{{turn.text}}</p><div class="message-files"><a v-for="r in turn.attachments||[]" :key="r.id" :href="contentUrl(r)"><StudioIcon name="document" :size="16"/>{{r.name}}</a></div></div><div class="assistant-message"><span class="reply-avatar" :class="partner.color">{{partner.initial}}</span><div class="assistant-content"><details v-if="turn.events?.length" class="execution-trace" :open="turn.status==='RUNNING'"><summary>{{turn.status==='RUNNING'?'正在执行 '+elapsed(turn):turn.status==='SUCCEEDED'?'执行完成':turn.status==='CANCELLED'?'已停止':'执行未完成'}} <span>⌄</span></summary><ol><li v-for="(e,i) in turn.events" :key="i"><StudioIcon name="check" :size="15"/><span>{{e.label}}</span></li></ol></details><strong v-else class="reply-name">{{partner.name}}</strong><p v-if="turn.modelSnapshot" class="partner-turn-model">{{turn.modelSnapshot.name}} · {{turn.modelSnapshot.model}}</p><ReplyMarkdown v-if="turn.answer" :text="turn.answer"/><p v-else class="turn-status">{{turn.status==='RUNNING'?'正在处理，请稍候…':turn.error}}</p><div class="artifact-cards"><div v-for="r in turn.artifacts||[]" :key="r.id"><button v-if="r.mime.startsWith('image/')" class="artifact-image" @click="preview=r"><img :src="contentUrl(r,true)" :alt="r.name" @load="bottom&&latest()"></button><a class="artifact-file" :href="contentUrl(r)" :download="r.name"><StudioIcon name="document" :size="24"/><strong>{{r.name}}</strong><StudioIcon name="download" :size="18"/></a></div></div><button v-if="turn.answer&&!turn.artifacts?.length" class="text-action" @click="exportLegacy(turn)">下载文稿</button></div></div></article>
   <div v-if="pending" class="pending-message"><p>{{pending.text}}</p><small>正在确认消息状态</small><button v-if="!busy" @click="send(true)">重试同一条消息</button></div>
  </div></div>
  <button v-if="!bottom" class="jump-latest" @click="latest" aria-label="回到最新消息">↓</button>
  <div id="task-composer" class="task-composer-dock"></div>
 </template>
 <Teleport v-if="!loading||active" :to="active?'#task-composer':'#landing-composer'" defer><div class="composer-width"><p v-if="error" class="composer-error" role="alert">{{error}} <button @click="error='';refresh()">刷新</button></p><form class="task-composer" @submit.prevent="send()"><div class="composer-attachments"><span v-for="(r,i) in attachments" :key="r.id">{{r.name}}<button type="button" @click="attachments.splice(i,1)" :aria-label="'移除'+r.name">×</button></span><span v-if="uploading">正在上传…</span></div><textarea v-model="draft" aria-label="发给伙伴的消息" maxlength="12000" :disabled="!enabled" :placeholder="!enabled?'此伙伴已被限制':active?'继续补充信息，或提出新的要求':'输入你的任务或目标'" @keydown.ctrl.enter.prevent="send()" @keydown.meta.enter.prevent="send()"></textarea><div class="composer-tools"><div class="composer-left"><button type="button" class="add-button" @click="menu=menu?'':'main'" :aria-expanded="!!menu" aria-label="添加附件或技能"><StudioIcon :name="menu?'close':'plus'" :size="24"/></button><button v-if="currentSkill?.inputs?.length" type="button" class="brief-button" aria-label="填写技能需求" :disabled="busy||running||!!pending" @click="brief=true">填写需求</button><button type="button" class="skill-chip" @click="menu='skills'"><StudioIcon name="layers" :size="14"/>{{currentSkill?.name||'自由对话'}}</button></div><PartnerModelPicker :partner-id="partner.id" v-model:model-profile-id="modelProfileId" :disabled="running||busy||!!pending" @ready="modelReady=$event"/><span class="composer-shortcut">Ctrl / ⌘ + Enter</span><button v-if="running" type="button" class="send-button stop-button" @click="stop" aria-label="停止任务">■</button><button v-else type="submit" class="send-button" aria-label="发送消息" :disabled="!enabled||busy||loading||uploading||!!pending||!modelReady||!draft.trim()">↑</button></div><div v-if="menu" class="composer-menu"><template v-if="menu==='main'"><button type="button" @click="fileInput.click()" :disabled="!enabled||uploading"><StudioIcon name="document"/>上传文件或图片</button><button type="button" @click="menu='skills'"><StudioIcon name="layers"/>选择技能 <span>›</span></button><button type="button" @click="menu='connectors'"><StudioIcon name="plug"/>选择连接器 <span>›</span></button><button type="button" @click="menu='resources'"><StudioIcon name="folder"/>引用任务资源</button><small>CSV / XLSX / TXT / MD / DOCX / 文字PDF / PNG / JPG · 每个≤1MB</small></template><template v-else-if="menu==='skills'"><div class="menu-heading"><button type="button" @click="menu='main'">‹</button>选择本轮技能</div><div class="skill-options"><button type="button" @click="skill='auto';menu=''" :class="{chosen:skill==='auto'}">自由对话 · 跟随本轮要求</button><small>伙伴推荐</small><button v-for="s in recommendedSkills" :key="s.id" type="button" @click="skill=s.id;menu=''" :class="{chosen:skill===s.id}">{{s.name}}</button><small>全部文字技能</small><button v-for="s in textSkills" :key="s.id" type="button" @click="skill=s.id;menu=''" :class="{chosen:skill===s.id}"><StudioIcon :name="s.icon" :size="20"/><span>{{s.name}}</span><span v-if="skill===s.id">✓</span></button></div></template><template v-else-if="menu==='resources'"><div class="menu-heading"><button type="button" @click="menu='main'">‹</button>引用任务资源</div><div class="skill-options"><button v-for="r in reusableResources" :key="r.id" type="button" @click="attachResource(r)">{{r.name}}</button><p v-if="!reusableResources.length">暂无可引用的任务资源</p></div></template><template v-else><div class="menu-heading"><button type="button" @click="menu='main'">‹</button>连接器</div><p>可在 MCP 页运行只读工具，再将成功结果引用到本伙伴作为材料；此对话不会自动调用 MCP。</p><RouterLink to="/mcp">查看 MCP 工具 →</RouterLink></template></div><input ref="fileInput" type="file" hidden multiple accept=".csv,.xlsx,.txt,.md,.docx,.pdf,.png,.jpg,.jpeg" @change="upload"></form><p v-if="active" class="composer-footnote">内容由 AI 生成，请核对重要信息<span v-if="attachments.some(r=>r.mime.startsWith('image/'))"> · 图片仅保存预览</span></p></div></Teleport>
 <Teleport to="body"><SkillBrief v-if="brief&&currentSkill" :skill="currentSkill" :draft="draft" @close="brief=false" @apply="draft=$event;brief=false"/></Teleport>
 <div v-if="preview" class="resource-preview" @click.self="preview=null"><button @click="preview=null" aria-label="关闭预览">×</button><img :src="contentUrl(preview,true)" :alt="preview.name"><a :href="contentUrl(preview)" :download="preview.name">下载 {{preview.name}}</a></div>
</section>
</template>
<style src="../partner-workspace.css"></style>
